@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (errorMessage is not null)
{
    <div class="alert alert-danger">@errorMessage</div>
}
else if (allTasks is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border spinner-border-sm" role="status"></div>
        <span>Loading tasks…</span>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="d-flex flex-wrap gap-3 mb-3">
        <span class="badge bg-secondary fs-6">Total: @allTasks.Count</span>
        @foreach (var col in columns)
        {
            <span class="badge bg-info text-dark fs-6">@col: @TasksForColumn(col).Count()</span>
        }
        <span class="badge bg-danger fs-6">Overdue: @allTasks.Count(t => t.DueDate.Date < DateTime.Today)</span>
    </div>

    <!-- Search bar -->
    <div class="mb-3" style="max-width:400px;">
        <input type="text" class="form-control" placeholder="Search tasks by title…"
               @bind="searchText" @bind:event="oninput" />
    </div>

    <!-- Kanban columns -->
    <div class="row g-3">
        @for (var i = 0; i < columns.Length; i++)
        {
            var colIndex = i;
            var colName = columns[colIndex];
            var colTasks = TasksForColumn(colName).ToList();

            <div class="col-md-4">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <strong>@colName</strong>
                        <span class="badge bg-primary rounded-pill">@colTasks.Count</span>
                    </div>
                    <div class="card-body d-flex flex-column gap-2 kanban-column">
                        @foreach (var task in colTasks)
                        {
                            <div class="card shadow-sm">
                                <div class="card-body p-2">
                                    <div class="fw-semibold mb-1">@task.Title</div>
                                    <div class="text-muted small mb-1">@task.Assignee</div>
                                    <div class="d-flex justify-content-between align-items-center mb-1">
                                        <span class="badge @PriorityClass(task.Priority)">@task.Priority</span>
                                        <span class="small text-muted">@task.DueDate.ToString("MMM dd")</span>
                                    </div>
                                    <div class="d-flex gap-1 mt-1">
                                        @if (colIndex > 0)
                                        {
                                            var leftStatus = columns[colIndex - 1];
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTask(task.Id, leftStatus)">
                                                ← Move Left
                                            </button>
                                        }
                                        @if (colIndex < columns.Length - 1)
                                        {
                                            var rightStatus = columns[colIndex + 1];
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="() => MoveTask(task.Id, rightStatus)">
                                                Move Right →
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (addingToColumn == colName)
                        {
                            <div class="card border-primary mt-auto">
                                <div class="card-body p-2 d-flex flex-column gap-2">
                                    <input type="text" class="form-control form-control-sm"
                                           placeholder="Title" @bind="newTitle" />
                                    <input type="text" class="form-control form-control-sm"
                                           placeholder="Assignee" @bind="newAssignee" />
                                    <select class="form-select form-select-sm" @bind="newPriority">
                                        <option value="High">High</option>
                                        <option value="Medium">Medium</option>
                                        <option value="Low">Low</option>
                                    </select>
                                    <input type="date" class="form-control form-control-sm"
                                           @bind="newDueDate" />
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm"
                                                @onclick="() => SaveNewTask(colName)"
                                                disabled="@isSaving">
                                            Save
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm"
                                                @onclick="CancelAdd">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                        else
                        {
                            <button class="btn btn-outline-primary btn-sm mt-auto"
                                    @onclick="() => StartAdd(colName)">
                                + Add Task
                            </button>
                        }
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private static readonly string[] columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem>? allTasks;
    private string? errorMessage;
    private string searchText = string.Empty;

    // Add-task form state
    private string? addingToColumn;
    private string newTitle = string.Empty;
    private string newAssignee = string.Empty;
    private string newPriority = "Medium";
    private DateTime newDueDate = DateTime.Today.AddDays(7);
    private bool isSaving;

    protected override async Task OnInitializedAsync()
    {
        try
        {
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
    }

    private IEnumerable<TaskItem> TasksForColumn(string status)
    {
        if (allTasks is null) return [];
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        return tasks;
    }

    private static string PriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var idx = allTasks!.FindIndex(t => t.Id == taskId);
            if (idx >= 0)
            {
                var old = allTasks[idx];
                allTasks[idx] = old with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private void StartAdd(string column)
    {
        addingToColumn = column;
        newTitle = string.Empty;
        newAssignee = string.Empty;
        newPriority = "Medium";
        newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd() => addingToColumn = null;

    private async Task SaveNewTask(string column)
    {
        if (string.IsNullOrWhiteSpace(newTitle)) return;

        isSaving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(newTitle.Trim(), newAssignee.Trim(), newPriority, newDueDate);
            allTasks!.Add(created);
            addingToColumn = null;
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            isSaving = false;
        }
    }
}

